// Basic TypeScript test
const message: string = "Hello from Deno sandbox!";
console.log(message);

// Test basic computation
const fib = (n: number): number => n <= 1 ? n : fib(n - 1) + fib(n - 2);
console.log(`Fibonacci(10) = ${fib(10)}`);

// Test async/await
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));
await delay(100);
console.log("Async works!");

// Test reading a file (should work - read access to cwd is default)
try {
  const text = await Deno.readTextFile("package.json");
  const pkg = JSON.parse(text);
  console.log(`Read package.json - name: ${pkg.name}`);
} catch (e) {
  console.error(`File read failed: ${e.message}`);
}

// Test writing a file (should fail - no write permission)
try {
  await Deno.writeTextFile("/tmp/deno-test.txt", "test");
  console.log("Write succeeded (unexpected)");
} catch (e) {
  console.log(`Write correctly blocked: ${e.constructor.name}`);
}

// Test network access (should fail - no net permission)
try {
  const resp = await fetch("https://example.com");
  console.log(`Fetch succeeded (unexpected): ${resp.status}`);
} catch (e) {
  console.log(`Network correctly blocked: ${e.constructor.name}`);
}

// Test environment variable access (should fail - no env permission)
try {
  const home = Deno.env.get("HOME");
  console.log(`Env access succeeded (unexpected): ${home}`);
} catch (e) {
  console.log(`Env correctly blocked: ${e.constructor.name}`);
}

// Test subprocess (should fail - no run permission)
try {
  const cmd = new Deno.Command("echo", { args: ["hello"] });
  const output = await cmd.output();
  console.log(`Subprocess succeeded (unexpected)`);
} catch (e) {
  console.log(`Subprocess correctly blocked: ${e.constructor.name}`);
}

console.log("\nAll tests complete!");

