// Test 1: Read file outside cwd (should fail)
try {
  const text = await Deno.readTextFile("/etc/hosts");
  console.log(`Read /etc/hosts succeeded (unexpected): ${text.slice(0, 50)}`);
} catch (e: unknown) {
  const err = e as Error;
  console.log(`Read outside cwd correctly blocked: ${err.constructor.name}`);
}

// Test 2: Directory listing within cwd
try {
  const entries: string[] = [];
  for await (const entry of Deno.readDir(".")) {
    entries.push(entry.name);
  }
  console.log(`\nDirectory listing (${entries.length} entries):`);
  console.log(entries.sort().slice(0, 10).join(", ") + "...");
} catch (e: unknown) {
  const err = e as Error;
  console.error(`Dir listing failed: ${err.message}`);
}

// Test 3: Deno.cwd()
try {
  console.log(`\nCurrent dir: ${Deno.cwd()}`);
} catch (e: unknown) {
  const err = e as Error;
  console.log(`cwd() blocked: ${err.constructor.name}`);
}

// Test 4: Web APIs (should work - these are built-in)
const url = new URL("https://example.com/path?q=test");
console.log(`\nURL parsing works: host=${url.host}, search=${url.search}`);

const encoded = btoa("Hello Deno!");
console.log(`Base64 encode: ${encoded}`);
console.log(`Base64 decode: ${atob(encoded)}`);

// Test 5: Crypto API
const data = new TextEncoder().encode("test message");
const hash = await crypto.subtle.digest("SHA-256", data);
const hashHex = [...new Uint8Array(hash)].map(b => b.toString(16).padStart(2, "0")).join("");
console.log(`\nSHA-256 of "test message": ${hashHex}`);

// Test 6: Performance API
const start = performance.now();
let sum = 0;
for (let i = 0; i < 1_000_000; i++) sum += i;
const elapsed = performance.now() - start;
console.log(`\n1M iterations in ${elapsed.toFixed(2)}ms (sum=${sum})`);

