// Test granted write permission to /tmp/deno-test
try {
  await Deno.mkdir("/tmp/deno-test", { recursive: true });
  await Deno.writeTextFile("/tmp/deno-test/hello.txt", "Written from sandbox!");
  const readBack = await Deno.readTextFile("/tmp/deno-test/hello.txt");
  console.log(`Write to /tmp/deno-test: "${readBack}"`);
} catch (e: unknown) {
  console.error(`Write failed: ${(e as Error).message}`);
}

// Test write to non-granted path still blocked
try {
  await Deno.writeTextFile("/tmp/other-place.txt", "nope");
  console.log("Write to /tmp/other-place.txt succeeded (unexpected)");
} catch (e: unknown) {
  console.log(`Write to non-granted path blocked: ${(e as Error).constructor.name}`);
}

// Test granted net permission to example.com
try {
  const resp = await fetch("https://example.com");
  const text = await resp.text();
  console.log(`\nFetch example.com: status=${resp.status}, body length=${text.length}`);
} catch (e: unknown) {
  console.error(`Fetch failed: ${(e as Error).message}`);
}

// Test net to non-granted host still blocked
try {
  const resp = await fetch("https://httpbin.org/get");
  console.log(`Fetch httpbin.org succeeded (unexpected): ${resp.status}`);
} catch (e: unknown) {
  console.log(`Fetch to non-granted host blocked: ${(e as Error).constructor.name}`);
}

// Cleanup
await Deno.remove("/tmp/deno-test", { recursive: true });
console.log("\nCleanup done");

export {};

